  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power Supply",
        "description": "Power supply assembly from which components are removed and into which they are installed.",
        "category": "power system"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "Fan installed in the power supply; its wires connect to J5 on the power board.",
        "category": "cooling"
      },
      {
        "component_id": "comp_fan_plenum",
        "name": "Fan plenum",
        "description": "Plenum attached to the fan casing.",
        "category": "cooling"
      },
      {
        "component_id": "comp_heat_exchange_coil",
        "name": "Heat exchange coil",
        "description": "Copper coil connected between the air-filter elbow fitting and the internal-compressor exhaust fitting.",
        "category": "air system"
      },
      {
        "component_id": "comp_internal_compressor",
        "name": "Internal compressor",
        "description": "Compressor installed inside the power supply, connected to the heat exchange coil and air filter.",
        "category": "air system"
      },
      {
        "component_id": "comp_air_filter",
        "name": "Air filter",
        "description": "Air filter connected to the heat exchange coil and fitted with a drain hose.",
        "category": "air system"
      },
      {
        "component_id": "comp_air_inlet_filter",
        "name": "Air inlet filter",
        "description": "Replaceable filter assembly screwed onto the internal compressor.",
        "category": "air system"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "Front panel of the power supply, described as a replaceable component.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_rear_panel",
        "name": "Rear panel",
        "description": "Power-supply panel that is detached during compressor replacement and tilted for access to the air inlet filter.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_center_panel",
        "name": "Center panel",
        "description": "Panel with notches used to route the fan and compressor wires.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board with connector J5 for the fan wires.",
        "category": "electrical"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Board with connector J2 for the internal compressor wires.",
        "category": "electrical"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "Barrier inside the power supply that is removed to access internal components.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "Cover removed and installed to provide access to components inside the power supply.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_j5_connector",
        "name": "J5 connector",
        "description": "Connector on the power board for the fan's red-and-black wires.",
        "category": "electrical connection"
      },
      {
        "component_id": "comp_j2_connector",
        "name": "J2 connector",
        "description": "Connector on the compressor-driver board for the internal compressor wires.",
        "category": "electrical connection"
      }
    ]
  },
  "relations": []
}
